{'code': "from qgis.PyQt.QtWidgets import QAction, QMenu
mw = iface.mainWindow()
matches = []
for a in mw.findChildren(QAction):
    t = a.text().replace('&','')
    if 'プロパティ' in t or 'Properties' in t.lower():
        parents = []
        try:
            for o in a.associatedObjects():
                if isinstance(o, QMenu):
                    parents.append('menu:' + (o.title() or o.objectName()))
                else:
                    parents.append(type(o).__name__)
        except Exception as e:
            parents.append('err:' + str(e))
        matches.append({
            'objectName': a.objectName(),
            'text': t,
            'enabled': a.isEnabled(),
            'visible': a.isVisible(),
            'parents': parents,
        })
result = matches"}
